import os
from decimal import Decimal, InvalidOperation
from typing import Any, Dict, List, Optional

import boto3


STANDARD_SCHEMA_VERSION = "1.0"


def _to_decimal(value: Any) -> Optional[str]:
    if value is None:
        return None
    if isinstance(value, (int, float, Decimal)):
        try:
            return format(Decimal(str(value)).quantize(Decimal("0.01")), "f")
        except (InvalidOperation, ValueError):
            return None
    if isinstance(value, str):
        cleaned = value.strip().replace(",", "")
        if not cleaned:
            return None
        try:
            return format(Decimal(cleaned).quantize(Decimal("0.01")), "f")
        except (InvalidOperation, ValueError):
            return None
    return None


def _safe_get(d: Dict[str, Any], *keys: str) -> Any:
    cur = d
    for key in keys:
        if not isinstance(cur, dict):
            return None
        cur = cur.get(key)
        if cur is None:
            return None
    return cur


def _field_text(field: Dict[str, Any]) -> Optional[str]:
    value_detection = field.get("ValueDetection") or {}
    text = value_detection.get("Text")
    if text:
        return str(text).strip()
    label_detection = field.get("LabelDetection") or {}
    text = label_detection.get("Text")
    return str(text).strip() if text else None


def _field_confidence(field: Dict[str, Any]) -> Optional[float]:
    value_detection = field.get("ValueDetection") or {}
    conf = value_detection.get("Confidence")
    if conf is not None:
        return float(conf)
    label_detection = field.get("LabelDetection") or {}
    conf = label_detection.get("Confidence")
    return float(conf) if conf is not None else None


def _group_summary_fields(summary_fields: List[Dict[str, Any]]) -> Dict[str, List[Dict[str, Any]]]:
    grouped: Dict[str, List[Dict[str, Any]]] = {}
    for field in summary_fields or []:
        field_type = _safe_get(field, "Type", "Text")
        if not field_type:
            continue
        grouped.setdefault(field_type, []).append(field)
    return grouped


def _pick_first_text(grouped: Dict[str, List[Dict[str, Any]]], *field_types: str) -> Optional[str]:
    for field_type in field_types:
        for field in grouped.get(field_type, []):
            text = _field_text(field)
            if text:
                return text
    return None


def _pick_first_amount(grouped: Dict[str, List[Dict[str, Any]]], *field_types: str) -> Optional[str]:
    for field_type in field_types:
        for field in grouped.get(field_type, []):
            amount = _safe_get(field, "ValueDetection", "NormalizedValue", "Value")
            normalized = _to_decimal(amount)
            if normalized is not None:
                return normalized
            text = _field_text(field)
            normalized = _to_decimal(text)
            if normalized is not None:
                return normalized
    return None


def _pick_max_confidence(grouped: Dict[str, List[Dict[str, Any]]], *field_types: str) -> Optional[float]:
    vals: List[float] = []
    for field_type in field_types:
        for field in grouped.get(field_type, []):
            conf = _field_confidence(field)
            if conf is not None:
                vals.append(conf)
    return max(vals) if vals else None


def _normalize_line_items(line_item_groups: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    for group in line_item_groups or []:
        for line_item in group.get("LineItems", []) or []:
            fields = {}
            for f in line_item.get("LineItemExpenseFields", []) or []:
                field_type = _safe_get(f, "Type", "Text")
                if field_type:
                    fields.setdefault(field_type, []).append(f)

            description = _pick_first_text(fields, "ITEM", "DESCRIPTION")
            quantity = _pick_first_text(fields, "QUANTITY")
            unit_price = _pick_first_amount(fields, "PRICE", "UNIT_PRICE")
            amount = _pick_first_amount(fields, "EXPENSE_ROW")

            items.append(
                {
                    "description": description,
                    "quantity": quantity,
                    "unit_price": unit_price,
                    "amount": amount,
                    "confidence": _pick_max_confidence(
                        fields, "ITEM", "DESCRIPTION", "QUANTITY", "PRICE", "UNIT_PRICE", "EXPENSE_ROW"
                    ),
                }
            )
    return items


def normalize_expense_document(document_bytes: bytes, region_name: Optional[str] = None) -> Dict[str, Any]:
    client = boto3.client("textract", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1")
    response = client.analyze_expense(Document={"Bytes": document_bytes})

    expense_documents = response.get("ExpenseDocuments", [])
    if not expense_documents:
        return {
            "schema_version": STANDARD_SCHEMA_VERSION,
            "provider": "aws_textract",
            "document_type": "expense",
            "documents": [],
        }

    normalized_documents: List[Dict[str, Any]] = []

    for expense_doc in expense_documents:
        grouped = _group_summary_fields(expense_doc.get("SummaryFields", []))

        vendor_name = _pick_first_text(grouped, "VENDOR_NAME", "SUPPLIER_NAME")
        vendor_address = _pick_first_text(grouped, "VENDOR_ADDRESS")
        invoice_id = _pick_first_text(grouped, "INVOICE_RECEIPT_ID")
        invoice_date = _pick_first_text(grouped, "INVOICE_RECEIPT_DATE")
        due_date = _pick_first_text(grouped, "DUE_DATE")
        currency = _pick_first_text(grouped, "CURRENCY")
        subtotal = _pick_first_amount(grouped, "SUBTOTAL")
        tax = _pick_first_amount(grouped, "TAX", "TOTAL_TAX")
        total = _pick_first_amount(grouped, "TOTAL")
        discount = _pick_first_amount(grouped, "DISCOUNT")
        shipping = _pick_first_amount(grouped, "SHIPPING_HANDLING_CHARGE")
        payment_terms = _pick_first_text(grouped, "PAYMENT_TERMS")

        bill_to = {
            "name": _pick_first_text(grouped, "BILL_TO"),
            "address": _pick_first_text(grouped, "BILL_TO_ADDRESS"),
        }
        ship_to = {
            "name": _pick_first_text(grouped, "SHIP_TO"),
            "address": _pick_first_text(grouped, "SHIP_TO_ADDRESS"),
        }

        line_items = _normalize_line_items(expense_doc.get("LineItemGroups", []))

        normalized_documents.append(
            {
                "expense_index": expense_doc.get("ExpenseIndex"),
                "document_id": invoice_id,
                "document_type": "invoice_or_receipt",
                "vendor": {
                    "name": vendor_name,
                    "address": vendor_address,
                },
                "bill_to": bill_to,
                "ship_to": ship_to,
                "dates": {
                    "invoice_date": invoice_date,
                    "due_date": due_date,
                },
                "amounts": {
                    "currency": currency,
                    "subtotal": subtotal,
                    "tax": tax,
                    "discount": discount,
                    "shipping": shipping,
                    "total": total,
                },
                "payment_terms": payment_terms,
                "line_items": line_items,
                "confidence": {
                    "vendor_name": _pick_max_confidence(grouped, "VENDOR_NAME", "SUPPLIER_NAME"),
                    "invoice_id": _pick_max_confidence(grouped, "INVOICE_RECEIPT_ID"),
                    "invoice_date": _pick_max_confidence(grouped, "INVOICE_RECEIPT_DATE"),
                    "total": _pick_max_confidence(grouped, "TOTAL"),
                },
                "raw": expense_doc,
            }
        )

    return {
        "schema_version": STANDARD_SCHEMA_VERSION,
        "provider": "aws_textract",
        "api": "AnalyzeExpense",
        "documents": normalized_documents,
    }
